package com.solace.mi;

import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.json.JsonMapper;

public class Core {
    private static final ObjectMapper MAPPER = JsonMapper.builder().build();
    private static final Pattern TOPIC_SEGMENT = Pattern.compile("[A-Za-z0-9_.-]+");

    public byte[] process(byte[] payload, Map<String, Object> headers) throws Exception {
        if (payload == null || payload.length == 0) {
            throw new IllegalArgumentException("Stripe webhook payload must not be empty");
        }
        if (headers == null) {
            throw new IllegalArgumentException("headers must not be null");
        }

        final JsonNode root;
        try {
            root = MAPPER.readTree(payload);
        } catch (Exception e) {
            throw new IllegalArgumentException("Stripe webhook payload must be valid JSON", e);
        }
        if (root == null || !root.isObject()) {
            throw new IllegalArgumentException("Stripe webhook payload must be a JSON object");
        }

        String eventId = requiredText(root, "id", "Stripe event id");
        String eventType = requiredText(root, "type", "Stripe event type");
        JsonNode data = root.get("data");
        if (data == null || !data.isObject()) {
            throw new IllegalArgumentException("Stripe event data must be an object");
        }
        JsonNode transaction = data.get("object");
        if (transaction == null || !transaction.isObject()) {
            throw new IllegalArgumentException("Stripe event data.object must be an expanded snapshot object");
        }

        String customerId = customerId(transaction.get("customer"));
        validateTopicSegment(eventType, "event type");
        validateTopicSegment(customerId, "customer id");

        String typeTopic = "stripe/transactions/" + eventType;
        String customerTopic = "stripe/customers/" + customerId + "/transactions";
        validateTopic(typeTopic);
        validateTopic(customerTopic);

        headers.put("stripe_event_id", eventId);
        headers.put("stripe_event_type", eventType);
        headers.put("mi_output_topics", List.of(typeTopic, customerTopic));
        return payload;
    }

    private static String requiredText(JsonNode object, String field, String label) {
        JsonNode value = object.get(field);
        if (value == null || !value.isTextual() || value.textValue().isEmpty()) {
            throw new IllegalArgumentException(label + " must be a non-empty string");
        }
        return value.textValue();
    }

    private static String customerId(JsonNode customer) {
        if (customer == null || customer.isNull()) {
            return "unknown";
        }
        if (customer.isTextual()) {
            if (customer.textValue().isEmpty()) {
                return "unknown";
            }
            return customer.textValue();
        }
        if (customer.isObject()) {
            JsonNode id = customer.get("id");
            if (id == null || id.isNull()) {
                return "unknown";
            }
            if (!id.isTextual()) {
                throw new IllegalArgumentException("Expanded Stripe customer id must be a string");
            }
            return id.textValue().isEmpty() ? "unknown" : id.textValue();
        }
        throw new IllegalArgumentException("Stripe customer must be a string, an expanded object, or null");
    }

    private static void validateTopicSegment(String value, String label) {
        if (!TOPIC_SEGMENT.matcher(value).matches()) {
            throw new IllegalArgumentException("Stripe " + label + " contains characters unsafe for a Solace topic segment");
        }
    }

    private static void validateTopic(String topic) {
        if (topic.length() > 250) {
            throw new IllegalArgumentException("Generated Solace topic exceeds 250 characters");
        }
    }
}

