package main
import("bytes";"encoding/json";"fmt";"regexp";"strings")
var stripeSegment=regexp.MustCompile(`^[A-Za-z0-9_.-]+$`)
func Process(payload []byte,headers map[string]any)([]byte,error){
 var event struct{ID string `json:"id"`;Type string `json:"type"`;Data *struct{Object map[string]json.RawMessage `json:"object"`} `json:"data"`}
 if err:=json.Unmarshal(payload,&event);err!=nil||strings.TrimSpace(event.ID)==""||event.Type==""||event.Data==nil||event.Data.Object==nil{return nil,fmt.Errorf("%w: invalid Stripe snapshot event",ErrInvalidInput)}
 customer:="unknown";raw:=event.Data.Object["customer"]
 if len(raw)>0&&!bytes.Equal(bytes.TrimSpace(raw),[]byte("null")){
  var value any;if json.Unmarshal(raw,&value)!=nil{return nil,ErrInvalidInput}
  switch typed:=value.(type){case string:if typed!=""{customer=typed};case map[string]any:if id,present:=typed["id"];present&&id!=nil{stringID,ok:=id.(string);if !ok{return nil,ErrInvalidInput};if stringID!=""{customer=stringID}};default:return nil,ErrInvalidInput}
 }
 if !stripeSegment.MatchString(event.Type)||!stripeSegment.MatchString(customer){return nil,fmt.Errorf("%w: unsafe topic segment",ErrInvalidInput)}
 eventTopic:="stripe/transactions/"+event.Type;customerTopic:="stripe/customers/"+customer+"/transactions"
 if len(eventTopic)>250||len(customerTopic)>250{return nil,ErrInvalidInput}
 headers["stripe_event_id"]=event.ID;headers["stripe_event_type"]=event.Type;headers["mi_output_topics"]=[]string{eventTopic,customerTopic}
 return payload,nil
}
